		if path != "" {
			message = path + ": " + message
		}

		location := Location{File: file}
		fallbackLine, fallbackColumn := 0, 0
		for _, pos := range m.InputPositions() {
			if pos.Line() == 0 || pos.Filename() == "" {
				continue
			}
			if file == "" || pos.Filename() == file {
				location.Line = pos.Line()
				location.Column = pos.Column()
				break
			}
			if fallbackLine == 0 {
				fallbackLine = pos.Line()
				fallbackColumn = pos.Column()
			}
		}
		if location.Line == 0 {
			location.Line = fallbackLine
			location.Column = fallbackColumn
		}

		result.Errors = append(result.Errors, Error{
			Message:  message,
			Path:     path,
			Location: location,
		})
	}

	if len(result.Errors) == 0 {
		result.Errors = append(result.Errors, Error{
			Message:  err.Error(),
			Location: Location{File: file},
		})
	}

	return result
}

func writeErrorDetails(format string, cerrs []Error, w io.Writer) error {
	var sb strings.Builder

	buildErrorMessage := func() {
		sb.WriteString("❌ Validation failure!\n\n")

		for i := 0; i < len(cerrs); i++ {
			errString := fmt.Sprintf(`
- Message: %s
  File   : %s
  Line   : %d
  Column : %d
`, cerrs[i].Message, cerrs[i].Location.File, cerrs[i].Location.Line, cerrs[i].Location.Column)

			sb.WriteString(errString)
		}
	}

	switch format {
	case jsonFormat:
		allErrors := struct {
			Errors []Error `json:"errors"`
		}{
			Errors: cerrs,
		}

		if err := json.NewEncoder(w).Encode(allErrors); err != nil {
			fmt.Fprintln(w, "Internal error.")
			return err
		}

		return nil
	case textFormat:
		buildErrorMessage()
	default:
		sb.WriteString("Invalid format chosen, defaulting to \"text\" format...\n")
		buildErrorMessage()
	}

	fmt.Fprint(w, sb.String())

	return nil
}

// ValidateFiles takes a slice of strings as filenames and validates them against
// our cue definition of features.
func ValidateFiles(dst io.Writer, files []string, format string) error {
	validator, err := NewFeaturesValidator()
	if err != nil {
		return err
	}

	cerrs := make([]Error, 0)

	for _, f := range files {
		b, err := os.ReadFile(f)
		if err != nil {
			cerrs = append(cerrs, Error{
				Message:  fmt.Sprintf("failed to read file: %v", err),
				Location: Location{File: f},
			})
			continue
		}
		result, err := validator.Validate(f, b)
		if err != nil && !errors.Is(err, ErrValidationFailed) {
			return err
		}
		cerrs = append(cerrs, result.Errors...)
	}

	if len(cerrs) > 0 {
		if err := writeErrorDetails(format, cerrs, dst); err != nil {
			return err
		}

		return ErrValidationFailed
	}

	// For json format upon success, return no output to the user
	if format == jsonFormat {
		return nil
	}

	if format != textFormat {
		fmt.Fprintln(dst, "Invalid format chosen, defaulting to \"text\" format...")
	}

	fmt.Fprintln(dst, "✅ Validation success!")

	return nil
}
